import * as M from './returns-model.js';
import {TEMPLATE_FIELDS,productReceipt,templateValue,matchesProductFilters,exportProductGrid} from './returns-fields.js';
import {TEMPLATE_URL,readImportFile,buildOrderDraft} from './returns-import.js';

const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const storeKey='mw-returns-prototype-v1';
let orders;try{const saved=JSON.parse(localStorage.getItem(storeKey)||'null');orders=Array.isArray(saved)&&saved.length?saved:M.seed();}catch{orders=M.seed();}
orders=M.migrate(orders);
let tab='全部',page=1,size=10,filters={},sort='created-desc',current=null,detailTab=0,draft=null,modalCommit=null,drawerMode='';
let importResult=null,importLoading=false,importSequence=0;
const hiddenCols=new Set(),detailTabs=['基础信息','预报货物','包裹跟踪 / 收货登记','客户认领','退换货库存','关联指令','费用与日志'];
const btn=(label,action,primary=false,extra='')=>`<button type="button" class="cl-btn ${primary?'primary':''}" data-rt-action="${action}" ${extra}>${label}</button>`;
const option=(value,label=value,selected='')=>`<option value="${esc(value)}" ${String(value)===String(selected)?'selected':''}>${esc(label)}</option>`;
const options=(values,selected='',first='全部')=>option('',first,selected)+values.map(v=>option(v,v,selected)).join('');
const input=(name,type='text',value='',attrs='')=>`<input name="${name}" type="${type}" value="${esc(value)}" ${attrs}>`;
const field=(label,control,required=false,wide=false)=>`<label class="cl-field ${wide?'cl-wide':''}"><span class="${required?'cl-required':''}">${label}</span>${control}</label>`;
const dt=t=>t?esc(String(t).replace('T',' ').slice(0,19)):'—';
const dateInput=t=>String(t||'').replace(' ','T').slice(0,19);
const badge=s=>`<span class="cl-badge ${['退回中','处理中','运输中','指令待处理','指令处理中'].includes(s)?'blue':['待认领','部分认领','待指令','待审批','待仓库确认'].includes(s)?'orange':['已完成','已入仓','已认领','已出库'].includes(s)?'green':['已关闭','审批拒绝','退回异常'].includes(s)?'red':''}">${esc(s)}</span>`;
const quantity=t=>t.receivedUnknown?(t.received?`${t.received} 个 + 未清点`:'未清点'):`${t.received} 个`;
const image=p=>p.image?`<img src="${esc(p.image)}" alt="${esc(p.name)}" data-rt-image="${esc(p.image)}" loading="lazy">`:'<span class="cl-image-empty">无图</span>';
const clients=()=>M.CLIENTS.map(c=>option(c.name,c.name+' · '+c.code)).join('');
const packageName=p=>p.tracking||'待登记追踪号';
const active=o=>!['已关闭','已完成'].includes(o.status);
const table=(heads,rows,extra='')=>`<div class="cl-scroll"><table class="cl-table rt-table ${extra}"><thead><tr>${heads.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows||`<tr><td colspan="${heads.length}" class="cl-empty">暂无记录</td></tr>`}</tbody></table></div>`;
const info=(label,value)=>`<div><dt>${label}</dt><dd>${value}</dd></div>`;
const toast=message=>{const e=$('#rtToast');e.textContent=message;e.hidden=false;clearTimeout(window.rtToastTimer);window.rtToastTimer=setTimeout(()=>e.hidden=true,4000);};
function persist(){try{localStorage.setItem(storeKey,JSON.stringify(orders));}catch{toast('本地存储空间不足，请导出当前记录');}}
function save(){window.ReturnsBridge?.sync(orders);persist();}
function reconcile(){for(const o of orders)for(const i of o.instructions){const state=window.ReturnsBridge?.status(i.id);if(state&&state!==i.status)M.syncInstruction(o,i.id,state);}save();}

const pageEl=document.createElement('main');pageEl.id='returnsPage';pageEl.className='content cl-page rt-page';pageEl.hidden=true;$('#warehousePlaceholderPage').after(pageEl);
document.body.insertAdjacentHTML('beforeend','<div id="rtDrawer" class="cl-overlay" hidden></div><div id="rtModal" class="cl-overlay cl-modal-overlay" hidden></div><div id="rtToast" class="cl-toast" role="status" hidden></div>');
pageEl.innerHTML=`<div class="cl-heading"><h2>退换货管理</h2></div><form id="rtFilter" class="cl-card cl-filter"><div class="cl-grid">
${field('关键字',input('keyword','search','','placeholder="退换货单号 / 产品名称 / SKU / 追踪单号"'))}${field('客户名称',input('customer','search','','list="rtCustomers" placeholder="客户名称或编码"')+`<datalist id="rtCustomers">${clients()}</datalist>`)}${field('退换货状态',`<select name="status">${options(M.STATUSES)}</select>`)}${field('收货状态',`<select name="receipt">${options(['未发运','运输中','待仓库确认','部分入仓','已入仓'])}</select>`)}${field('退回仓库',`<select name="warehouse">${options(M.WAREHOUSES)}</select>`)}${field('申请时间',`<div class="cl-range">${input('from','date','','aria-label="申请开始日期"')}<span>至</span>${input('to','date','','aria-label="申请结束日期"')}</div>`)}</div>
<div id="rtAdvanced" class="cl-advanced" hidden><div class="cl-filter-heading">模板产品条件</div><div class="cl-grid"><label class="cl-field"><span>产品名称</span><input type="search" name="productName" placeholder="输入产品名称"></label><label class="cl-field"><span>SKU</span><input type="search" name="sku" placeholder="输入SKU"></label><label class="cl-field"><span>操作要求</span><input type="search" name="requirement" placeholder="输入操作要求"></label><label class="cl-field"><span>货物目前所在地</span><input type="search" name="location" placeholder="输入货物目前所在地"></label><label class="cl-field"><span>退仓时间</span><div class="cl-range"><input name="returnedFrom" type="date" aria-label="退仓开始日期"><span>至</span><input name="returnedTo" type="date" aria-label="退仓结束日期"></div></label><label class="cl-field"><span>预报产品数量(个)</span><div class="cl-range"><input name="quantityMin" type="number" min="0" step="1" placeholder="最小值"><span>至</span><input name="quantityMax" type="number" min="0" step="1" placeholder="最大值"></div></label><label class="cl-field"><span>单个产品重量(KG)</span><div class="cl-range"><input name="weightMin" type="number" min="0" step="any" placeholder="最小值"><span>至</span><input name="weightMax" type="number" min="0" step="any" placeholder="最大值"></div></label><label class="cl-field"><span>装箱数量</span><div class="cl-range"><input name="packingMin" type="number" min="0" step="1" placeholder="最小值"><span>至</span><input name="packingMax" type="number" min="0" step="1" placeholder="最大值"></div></label></div><div class="cl-filter-heading cl-filter-secondary">业务条件</div><div class="cl-grid">${field('认领状态',`<select name="claim">${options(['待认领','部分认领','已认领'])}</select>`)}${field('退件来源',`<select name="source">${options(M.SOURCES)}</select>`)}${field('物流商',`<select name="carrier">${options(['UPS','FedEx','USPS','AMZL','其他'])}</select>`)}${field('追踪单号',input('tracking','search','','placeholder="输入追踪单号"'))}${field('入库时间',`<div class="cl-range">${input('receivedFrom','date','','aria-label="入库开始日期"')}<span>至</span>${input('receivedTo','date','','aria-label="入库结束日期"')}</div>`)}${field('收货异常',`<select name="exception">${options(['是','否'])}</select>`)}${field('已下指令',`<select name="instruction">${options(['是','否'])}</select>`)}${field('关联原运单号',input('originalTracking','search'))}${field('退件核实工单号',input('ticket','search'))}</div></div><div class="cl-filter-actions"><button class="cl-btn primary" type="submit">⌕ 搜索</button>${btn('重置','reset')}${btn('展开 ⌄','expand')}</div></form>
<section class="cl-card"><div id="rtTabs" class="cl-tabs"></div><div class="cl-toolbar cl-list-toolbar"><div class="cl-toolbar-left">${btn('＋ 模板导入下单','create',true)}${btn('查看日志','list-logs')}${btn('↓ 导出','export')}</div><div class="cl-toolbar-right"><span id="rtSummary" class="cl-muted"></span><select id="rtSort" class="rt-sort" aria-label="列表排序">${option('created-desc','申请时间：新到旧')}${option('updated-desc','更新时间：新到旧')}${option('created-asc','申请时间：旧到新')}${option('forecast-desc','预报数量：多到少')}</select>${btn('☷ 列设置','columns')}</div></div><div id="rtColumns" class="cl-columns" hidden></div><div class="cl-scroll"><table class="cl-table rt-table"><thead id="rtHead"></thead><tbody id="rtBody"></tbody></table></div><div id="rtFooter" class="cl-footer"></div></section>`;
const templateCols=TEMPLATE_FIELDS.map(({key,label})=>[key,label]);
const businessCols=[['warehouse','退回仓库'],['source','退件来源'],['status','退换货状态'],['receipt','收货状态'],['claim','认领状态'],['created','申请时间'],['updated','最近更新时间']];
const cols=[['id','退换货单号'],...templateCols,...businessCols];
const columnControls=columns=>columns.map(([key,label])=>`<label><input type="checkbox" data-rt-column="${key}" checked>${label}</label>`).join('');
$('#rtColumns').innerHTML=[['下单模板字段',templateCols],['业务信息',businessCols]].map(([title,columns])=>`<div class="cl-column-group"><strong>${title}</strong><div>${columnControls(columns)}</div></div>`).join('');
function templateHTML(o,p,key,reported=false){
  const value=templateValue(o,p,key,{reported});
  if(key==='image')return `<div class="cl-product cl-list-image">${p?image(p):'<span class="cl-image-empty">无图</span>'}</div>`;
  if(key==='tracking'&&!reported)return value?`<button class="cl-link rt-tracking-link" data-rt-action="packages" title="${esc(value)}">${esc(value).replaceAll('；','<br>')}</button>`:'—';
  let result=value===''||value===null||value===undefined?'—':esc(value).replaceAll('；','<br>');
  if(!reported&&p&&['reportedReceivedAt','reportedReceived','reportedBoxes'].includes(key)&&p[key]!==null&&p[key]!==undefined&&p[key]!=='')result+=`<div class="cl-subline rt-template-reference">模板填写：${esc(p[key])}${productReceipt(o,p).times.length?'':' · 待仓库核实'}</div>`;
  return result;
}
function matches(o){const f=filters,has=(value,search)=>String(value||'').toLowerCase().includes(String(search||'').trim().toLowerCase());if(f.keyword&&!has([o.id,...o.products.flatMap(p=>[p.name,p.sku,p.tracking,p.requirement,p.location]),...o.packages.map(p=>p.tracking)].join(' '),f.keyword))return false;if(f.customer&&!has(o.customer+' '+o.customerCode,f.customer))return false;for(const k of['warehouse','source','status','ticket','originalTracking'])if(f[k]&&(k==='ticket'||k==='originalTracking'?!has(o[k],f[k]):o[k]!==f[k]))return false;if(f.receipt&&M.receiptStatus(o)!==f.receipt||f.claim&&M.claimStatus(o)!==f.claim)return false;if(f.from&&o.created.slice(0,10)<f.from||f.to&&o.created.slice(0,10)>f.to)return false;if(f.carrier&&!o.packages.some(p=>p.carrier===f.carrier)||f.tracking&&!o.packages.some(p=>has(p.tracking,f.tracking))&&!o.products.some(p=>has(p.tracking,f.tracking)))return false;if((f.receivedFrom||f.receivedTo)&&!o.receipts.some(r=>(!f.receivedFrom||r.time.slice(0,10)>=f.receivedFrom)&&(!f.receivedTo||r.time.slice(0,10)<=f.receivedTo)))return false;if(!matchesProductFilters(o,f))return false;const exception=o.receipts.some(r=>r.difference)||o.packages.some(p=>p.logistics==='退回异常');if(f.exception&&(f.exception==='是')!==Boolean(exception)||f.instruction&&(f.instruction==='是')!==Boolean(o.instructions.length))return false;return true;}
const filtered=()=>orders.filter(matches).filter(o=>tab==='全部'||o.status===tab);
function operations(o){
  const choices=[['edit','编辑预报'],['accept','受理'],['reject','拒绝受理'],['track','登记追踪号'],['receive','登记收货'],['notify','通知认领'],['claim','确认认领'],['instruct','下指令'],['close','取消申请']].filter(([action])=>M.can(o,action));
  const primary={待受理:'accept',待退回:'track',退回中:'receive',待认领:'claim',待指令:'instruct',处理中:'instruct'}[o.status];
  const leading=choices.filter(([action])=>action==='edit'||action===primary),remaining=choices.filter(([action])=>action!=='edit'&&action!==primary);
  const actionButtons=actions=>actions.map(([action,label])=>`<button type="button" class="cl-link" data-rt-action="${action}">${label}</button>`).join('');
  return actionButtons(leading)+'<button type="button" class="cl-link" data-rt-action="detail">详情</button>'+actionButtons(remaining)+'<button type="button" class="cl-link" data-rt-action="logs">查看日志</button>';
}
function render(){
  const base=orders.filter(matches),rows=filtered().sort((a,b)=>sort==='forecast-desc'?M.totals(b).forecast-M.totals(a).forecast:sort==='created-asc'?a.created.localeCompare(b.created):String(b[sort==='updated-desc'?'updated':'created']).localeCompare(String(a[sort==='updated-desc'?'updated':'created']))),pages=Math.max(1,Math.ceil(rows.length/size));
  page=Math.min(page,pages);
  $('#rtTabs').innerHTML=[...M.STATUSES,'全部'].map(s=>`<button type="button" class="${tab===s?'active':''}" data-rt-tab="${s}">${s}<span class="cl-count">${base.filter(o=>s==='全部'||o.status===s).length}</span></button>`).join('');
  const visible=cols.filter(([key])=>!hiddenCols.has(key));
  $('#rtHead').innerHTML='<tr>'+visible.map(([key,label])=>`<th class="rt-list-col-${key}">${label}</th>`).join('')+'<th class="cl-fixed">操作</th></tr>';
  $('#rtBody').innerHTML=rows.slice((page-1)*size,page*size).flatMap(o=>(o.products.length?o.products:[null]).map(p=>{
    const values={id:`<button class="cl-link cl-mono" data-rt-action="detail">${esc(o.id)}</button>`,...Object.fromEntries(TEMPLATE_FIELDS.map(({key})=>[key,templateHTML(o,p,key)])),warehouse:esc(o.warehouse),source:esc(o.source),status:badge(o.status),receipt:badge(M.receiptStatus(o)),claim:badge(M.claimStatus(o)),created:dt(o.created),updated:dt(o.updated)};
    if(!p){values.name='待核实';values.quantity=M.totals(o).forecast;values.reportedReceived=quantity(M.totals(o));values.reportedBoxes=M.totals(o).boxes+' 箱';}
    return `<tr data-rt-order="${esc(o.id)}" data-rt-product="${esc(p?.id||'')}">${visible.map(([key])=>`<td class="rt-list-col-${key}">${values[key]}</td>`).join('')}<td class="cl-fixed cl-row-actions"><div class="cl-action-set">${operations(o)}</div></td></tr>`;
  })).join('')||`<tr><td colspan="${visible.length+1}" class="cl-empty">暂无匹配的退换货申请</td></tr>`;
  $('#rtSummary').textContent='共 '+rows.length+' 条申请 · '+rows.reduce((n,o)=>n+Math.max(o.products.length,1),0)+' 行产品';
  $('#rtFooter').innerHTML=`<span>共 ${rows.length} 条</span>${btn('‹','prev',false,page===1?'disabled':'')}${Array.from({length:pages},(_,i)=>`<button class="cl-btn ${page===i+1?'primary':''}" data-rt-page="${i+1}">${i+1}</button>`).join('')}${btn('›','next',false,page===pages?'disabled':'')}<select id="rtPageSize" aria-label="每页数量">${[10,20,50].map(n=>option(n,n+' 条/页',size)).join('')}</select>`;
}
function open(orderId=''){if(!window.confirmDiscardInstructionStatusDrafts())return;window.activateWarehousePage('returns','退换货管理','#navReturnsManagement');reconcile();pageEl.hidden=false;render();if(orderId){const o=orders.find(o=>o.id===orderId);if(o)detail(o);}}
function boxRows(o){return o.boxes.map(b=>`<tr><td class="cl-mono">${esc(b.id)}</td><td>${esc(b.storageNo)}</td><td>${esc(packageName(o.packages.find(p=>p.id===b.packageId)||{}))}</td><td>${dt(b.receivedAt)}</td><td>${b.counted?b.items.reduce((n,i)=>n+i.quantity,0)+' 个':'未清点'}</td><td>${esc(b.customer||'待识别')}</td><td>${badge(b.claimed?'已认领':'待认领')}</td><td>${b.outbound?'0':'1'} 箱</td><td>${b.reservedBy?'1':'0'} 箱</td><td>${!b.outbound&&b.claimed&&!b.reservedBy&&b.customerCode===o.customerCode?'1':'0'} 箱</td><td>${b.outbound?'1':'0'} 箱</td></tr>`).join('');}
function instructionActions(i){const attr=`data-rt-instruction="${esc(i.id)}"`;let actions=btn('查看指令','open-instruction',false,attr);if(i.status==='指令处理完成、待出库'&&i.type!=='库内增值服务')actions+=btn(i.type==='销毁'?'确认实际销毁':i.type==='自提'?'确认实际提货':'确认实际出库','confirm-outbound',true,attr);return actions;}
function detail(o,index=0){$('#rtDrawer').classList.remove('cl-import-overlay');importSequence++;current=o;detailTab=index;drawerMode='detail';const t=M.totals(o);let body='';
  if(index===0)body=`<section class="cl-section"><h3>申请信息</h3><dl class="rt-read-grid">${info('客户名称 / 编码',esc(o.customer||'待识别货主')+' / '+esc(o.customerCode||'待识别'))}${info('退回仓库',esc(o.warehouse))}${info('退件来源',esc(o.source))}${info('退件原因',esc(o.reason||'待核实'))}${info('处理诉求',esc(o.request||'暂时未确定'))}${info('原运单号',esc(o.originalTracking||'—'))}${info('受理人',esc(o.acceptedBy||'—'))}${info('受理时间',dt(o.acceptedAt))}${info('申请时间',dt(o.created))}${info('最近更新',dt(o.updated))}${info('申请备注',esc(o.remark||'—'))}${o.closedReason?info('关闭原因',esc(o.closedReason)):''}</dl></section><section class="cl-section"><div class="cl-heading"><h3 style="margin:0">退件核实工单</h3>${active(o)?btn('关联 / 更新工单','ticket'):''}</div><dl class="rt-read-grid">${info('工单号',esc(o.ticket||'未关联'))}${info('工单进度',esc(o.ticketStatus||'未关联'))}</dl><p class="cl-muted">核实工单关闭不改变实际收货或退换货处理状态。</p></section><section class="cl-section"><h3>业务须知</h3><div class="cl-notice"><ul><li>退件入仓以海外仓实际确认收到为准，物流官网签收仅作参考。</li><li>请及时提供全部追踪单号、物流商及包裹产品个数。带电、危险品等特殊货物需另行确认受理和报价。</li><li>仓库默认不对内件开箱清点，清点、换标及重打板等费用按实际报价记录。</li><li>免仓期限、认领期限及仓储费用按对应业务线和仓库确认，不自动计费或销毁。</li></ul></div></section>`;
  if(index===1)body=`<section class="cl-section"><h3>预报货物明细</h3>${table(TEMPLATE_FIELDS.map(f=>f.label),o.products.map(p=>`<tr>${TEMPLATE_FIELDS.map(({key})=>`<td class="rt-list-col-${key}">${templateHTML(o,p,key)}</td>`).join('')}</tr>`).join(''))}<p class="cl-muted">每个产品单独一行。入库信息以仓库实际收货登记为准，模板填写的入库数据作为核对参考；多 SKU 同箱的关联箱数不能相加。</p></section>`;
  if(index===2)body=`<section class="cl-section"><div class="cl-heading"><h3 style="margin:0">退回包裹</h3>${M.can(o,'track')?btn('＋ 登记追踪号','track',true):''}</div>${table(['追踪单号','物流商','预报产品个数','关联 SKU / 数量','退仓时间','发运时间','预计送达','物流反馈','仓库确认','操作'],o.packages.map(p=>`<tr><td>${esc(packageName(p))}</td><td>${esc(p.carrier)}</td><td>${p.forecast} 个</td><td>${p.items.map(i=>esc(o.products.find(k=>k.id===i.productId)?.sku||i.productId)+' × '+i.quantity).join('<br>')||'待核实'}</td><td>${dt(p.returnedAt)}</td><td>${dt(p.shipped)}</td><td>${dt(p.eta)}</td><td>${badge(p.logistics||'未发运')}</td><td>${badge(p.received?'已核实收齐':o.receipts.some(r=>r.packageId===p.id)?'部分收到':'未确认收货')}</td><td class="rt-inline-actions">${active(o)?btn('物流反馈','logistics',false,`data-rt-package="${p.id}"`):''}${M.can(o,'receive')&&!p.received?btn('登记收货','receive',false,`data-rt-package="${p.id}"`):''}</td></tr>`).join(''))}</section><section class="cl-section"><h3>实际收货记录</h3>${table(['收货记录','追踪单号','入库时间','入库个数(个)','入库件数(箱)','SKU 实收','差异原因','收货备注','附件'],o.receipts.map(r=>`<tr><td>${esc(r.id)}</td><td>${esc(packageName(o.packages.find(p=>p.id===r.packageId)||{}))}</td><td>${dt(r.time)}</td><td>${r.counted?r.items.reduce((n,i)=>n+i.quantity,0)+' 个':'未清点'}</td><td>${r.boxes} 箱</td><td>${r.counted?r.items.map(i=>esc(o.products.find(p=>p.id===i.productId)?.sku||i.productId)+' × '+i.quantity).join('<br>'):'仅收包裹，未开箱'}</td><td>${esc(r.difference||'—')}</td><td>${esc(r.note||'—')}</td><td>${r.image?`<div class="cl-product">${image({name:'收货附件',image:r.image})}</div>`:'—'}</td></tr>`).join(''))}</section>`;
  if(index===3)body=`<section class="cl-section"><div class="cl-heading"><h3 style="margin:0">客户认领</h3><div class="rt-controls">${M.can(o,'notify')?btn('通知认领','notify'):''}${M.can(o,'claim')?btn('确认认领','claim',true):''}</div></div>${table(['包裹 / 箱号','关联客户','认领状态','通知时间','认领时间','确认人','认领备注'],o.boxes.map(b=>`<tr><td>${esc(packageName(o.packages.find(p=>p.id===b.packageId)||{}))}<div class="cl-subline">${esc(b.id)}</div></td><td>${esc(b.customer||'待识别货主')}<div class="cl-subline">${esc(b.customerCode||'—')}</div></td><td>${badge(b.claimed?'已认领':'待认领')}</td><td>${dt(b.notifiedAt)}</td><td>${dt(b.claimedAt)}</td><td>${esc(b.claimedBy||'—')}</td><td>${esc(b.claimNote||'—')}</td></tr>`).join(''))}</section>`;
  if(index===4)body=`<section class="cl-section"><div class="cl-heading"><h3 style="margin:0">退换货在库明细</h3>${M.can(o,'instruct')?btn('下指令','instruct',true):''}</div>${table(['箱号','库存记录','追踪单号','入库时间','内件个数','所属客户','认领状态','在库(箱)','占用(箱)','可用(箱)','已出库(箱)'],boxRows(o))}<p class="cl-muted">在此查看退换货在库箱并下指令。只对已收、已认领且可用的具体箱下指令。</p></section>`;
  if(index===5)body=`<section class="cl-section"><div class="cl-heading"><h3 style="margin:0">关联指令</h3>${M.can(o,'instruct')?btn('＋ 下指令','instruct',true):''}</div>${table(['指令单号','来源退换货单','指令类型','关联箱号 / 数量','审批状态','执行状态','创建时间','操作人','操作'],o.instructions.map(i=>`<tr><td>${esc(i.id)}</td><td>${esc(o.id)}</td><td>${esc(i.type)}</td><td>${i.boxIds.map(esc).join('<br>')}<div class="cl-subline">${i.boxIds.length} 箱</div></td><td>${badge(i.status==='待审批'?'待审批':i.status==='审批拒绝'?'审批拒绝':'已通过')}</td><td>${badge(i.status)}</td><td>${dt(i.created)}</td><td>${esc(i.operator)}</td><td class="rt-inline-actions">${instructionActions(i)}</td></tr>`).join(''))}<div class="cl-notice" style="margin-top:16px">审批和仓库执行在指令管理中处理，此处同步展示关联进度。处理完成后在此确认实际出库、提货或销毁。增值服务完成不等于实际出库。</div></section>`;
  if(index===6)body=`<section class="cl-section"><div class="cl-heading"><h3 style="margin:0">费用记录</h3>${M.can(o,'fee')?btn('＋ 登记费用','fee'):''}</div>${table(['费用项目','报价金额','币种','登记时间','登记人','备注'],o.fees.map(f=>`<tr><td>${esc(f.name)}</td><td>${Number(f.amount).toFixed(2)}</td><td>${esc(f.currency)}</td><td>${dt(f.time)}</td><td>${esc(f.operator)}</td><td>${esc(f.note||'—')}</td></tr>`).join(''))}<p class="cl-muted">按实际报价登记费用，不预设统一收费标准。</p></section><section class="cl-section"><h3>操作日志</h3><ol class="cl-timeline">${o.logs.map(l=>`<li><strong>${esc(l.action)}</strong><span class="cl-muted" style="float:right">${dt(l.time)}</span><p>${esc(l.note)}</p><span class="cl-muted">${esc(l.operator)}</span></li>`).join('')}</ol></section>`;
  const buttons=[['edit','编辑预报'],['accept','受理'],['track','登记追踪号'],['receive','登记收货'],['claim','确认认领'],['instruct','下指令']].filter(([a])=>M.can(o,a)).map(([a,label])=>btn(label,a,a==='instruct')).join('');
  $('#rtDrawer').innerHTML=`<section class="cl-drawer rt-drawer" role="dialog" aria-modal="true" aria-label="退换货详情"><header class="cl-drawer-header"><div><h2>退换货详情 <span class="cl-muted cl-mono">${esc(o.id)}</span></h2><p>${esc(o.customer||'待识别货主')} · ${esc(o.customerCode||'未确认')} · ${esc(o.warehouse)}</p><div class="rt-status-summary">${badge(o.status)}${badge(M.receiptStatus(o))}${badge(M.claimStatus(o))}</div></div><button class="cl-close" data-rt-action="drawer-close" aria-label="关闭详情">×</button></header><div class="rt-metrics"><div><span>预报总个数</span><b>${t.forecast}</b><small>个</small></div><div><span>实际入库个数</span><b>${t.receivedUnknown?'未清点':t.received}</b><small>${t.receivedUnknown&&t.received?'已清点 '+t.received+' 个':'个'}</small></div><div><span>实际入库箱数</span><b>${t.boxes}</b><small>箱</small></div><div><span>可下指令箱数</span><b>${t.available}</b><small>箱</small></div></div><div class="rt-detail-actions">${buttons}</div><div class="cl-tabs rt-detail-tabs">${detailTabs.map((title,i)=>`<button type="button" class="${i===index?'active':''}" data-rt-detail-tab="${i}">${title}</button>`).join('')}</div><div class="cl-drawer-body">${body}</div><footer class="cl-drawer-footer"><span class="cl-muted">${t.inStock} 箱在库 · ${t.reserved} 箱占用 · ${t.outbound} 箱已出库</span>${btn('关闭','drawer-close')}</footer></section>`;$('#rtDrawer').hidden=false;
}

function createImport(){
  closeDrawer();current=null;draft=null;drawerMode='import';importResult=null;importLoading=false;importSequence++;
  $('#rtDrawer').classList.add('cl-import-overlay');
  $('#rtDrawer').innerHTML=`<section class="cl-drawer cl-create rt-import-drawer" role="dialog" aria-modal="true" aria-label="新增退换货"><header class="cl-drawer-header"><div><h2>新增退换货</h2><p class="cl-muted">模板导入下单 · 每个产品单独一行</p></div><button class="cl-close" data-rt-action="drawer-close" aria-label="关闭">×</button></header><div class="cl-drawer-body"><form id="rtImportForm"><section class="cl-section"><h3>基础信息</h3><div class="rt-product-grid">
  ${field('客户名称',`<select name="customer" required>${option('','请选择客户')}${M.CLIENTS.map(c=>option(c.name,c.name+' · '+c.code)).join('')}</select>`,true)}
  ${field('客户编码',input('customerCode','text','','readonly'))}
  ${field('退回仓库',`<select name="warehouse" required>${options(M.WAREHOUSES,'','请选择仓库')}</select>`,true)}
  ${field('退件来源',`<select name="source">${M.SOURCES.map(v=>option(v)).join('')}</select>`)}
  ${field('退件原因',`<select name="reason">${['客户退货','拒收','错投','地址问题','其他'].map(v=>option(v)).join('')}</select>`)}
  ${field('处理诉求',`<select name="request">${['暂时未确定','换标重新派送','清点','自提','销毁','其他'].map(v=>option(v)).join('')}</select>`)}
  ${field('原运单号',input('originalTracking'))}${field('退件核实工单号',input('ticket'))}${field('申请备注','<textarea name="remark" maxlength="1000"></textarea>')}
  </div><label class="cl-consent"><input name="ownerUnknown" type="checkbox" disabled>客户归属待核实（代理反馈或其他退件）</label></section><section class="cl-section"><h3>退换货模板导入</h3><div class="cl-import-steps"><div><b>1</b><strong>下载并填写退换货模板</strong><span>每行登记一个产品</span></div><i>›</i><div><b>2</b><strong>上传退换货文件</strong><span>支持 Excel / CSV</span></div><i>›</i><div><b>3</b><strong>校验后提交下单</strong><span>整张申请包含全部产品</span></div></div><div class="cl-import-upload"><a class="cl-btn" href="${esc(TEMPLATE_URL)}" download="退换货导入模板.xlsx">↓ 下载退换货模板</a><label class="cl-file-button">↑ 上传退换货文件<input id="rtImportFile" type="file" accept=".xlsx,.csv"></label><span id="rtImportFileName" class="cl-muted">尚未选择文件</span></div><div class="cl-notice">请保留模板的 15 列字段及顺序，每行一个产品。产品名称、SKU 和预报产品数量必填；客户名称可沿用页面选择。图片可填写链接，外箱尺寸填写长×宽×高（cm）。模板内的入库信息可留空，实际收货由仓库登记。最多支持 500 行。</div><div id="rtImportPreview" style="margin-top:18px"></div></section><label class="cl-consent"><input name="consent" type="checkbox" required>我已确认预报资料，知悉退件以海外仓实际收到为准</label><p id="rtImportError" class="cl-error" role="alert"></p></form></div><footer class="cl-drawer-footer"><span class="cl-muted">校验通过后生成退换货单号，进入待受理</span>${btn('取消','drawer-close')}<button class="cl-btn primary" id="rtImportSubmit" type="submit" form="rtImportForm" disabled>确认导入并提交下单</button></footer></section>`;
  $('#rtDrawer').hidden=false;syncImportCustomer();
}
function syncImportCustomer(){
  const f=$('#rtImportForm');if(!f)return;
  f.elements.ownerUnknown.disabled=f.elements.source.value==='客户预报';if(f.elements.ownerUnknown.disabled)f.elements.ownerUnknown.checked=false;
  const unknown=f.elements.ownerUnknown.checked;f.elements.customer.disabled=unknown;f.elements.customer.required=!unknown;
  f.elements.customerCode.value=unknown?'':M.CLIENTS.find(c=>c.name===f.elements.customer.value)?.code||'';renderImportPreview();
}
function renderImportPreview(){
  const el=$('#rtImportPreview');if(!el)return;
  const f=$('#rtImportForm'),unknown=f?.elements.ownerUnknown.checked,customer=unknown?'':f?.elements.customer.value||'',rows=importResult?.rows.map(row=>({...row,errors:[...row.errors,...(row.customer&&(unknown||customer&&row.customer!==customer)?['客户名称与页面选择不一致']:[])]}))||[];
  const errors=rows.filter(row=>row.errors.length).length;
  $('#rtImportSubmit').disabled=importLoading||!importResult?.total||errors>0;
  if(importLoading){el.innerHTML='<div class="cl-import-empty">正在解析文件并校验产品资料…</div>';return;}
  if(!importResult){el.innerHTML='<div class="cl-import-empty">上传填写好的退换货模板后，在这里预览产品与校验结果</div>';return;}
  el.innerHTML=`<div class="cl-import-summary"><span>产品 <b>${rows.length}</b> 行</span><span>通过 <b class="cl-success">${rows.length-errors}</b> 行</span><span>错误 <b class="${errors?'cl-danger':''}">${errors}</b> 行</span><span>预报产品 <b>${rows.filter(row=>!row.errors.length).reduce((n,row)=>n+row.product.quantity,0)}</b> 个</span></div>${errors?'<div class="cl-notice warning" style="margin-bottom:12px">存在错误行，请按行号修改模板并重新上传。</div>':''}<p class="cl-muted">按退换货模板的 15 列顺序预览，可横向滚动。多追踪号产品提交后需在包裹登记中确认各包裹个数。</p>${table(['模板行号',...TEMPLATE_FIELDS.map(f=>f.label),'校验结果'],rows.map(row=>`<tr class="${row.errors.length?'cl-import-invalid':''}"><td>${row.line}</td>${TEMPLATE_FIELDS.map(({key})=>`<td class="rt-list-col-${key}">${templateHTML({customer:row.customer||customer},row.product,key,true)}</td>`).join('')}<td class="cl-validation">${row.errors.length?row.errors.map(error=>`<div>${esc(error)}</div>`).join(''):'<span class="cl-success">✓ 校验通过</span>'}</td></tr>`).join(''))}`;
}
async function loadImport(file){
  const sequence=++importSequence;importLoading=true;importResult=null;$('#rtImportError').textContent='';$('#rtImportFileName').textContent=file.name;renderImportPreview();
  try{const result=await readImportFile(file);if(sequence===importSequence&&drawerMode==='import')importResult=result;}
  catch(error){if(sequence===importSequence&&drawerMode==='import')$('#rtImportError').textContent=error.message;}
  finally{if(sequence===importSequence&&drawerMode==='import'){importLoading=false;renderImportPreview();}}
}
function submitImport(e){
  e.preventDefault();
  try{
    const f=e.target;if(!f.reportValidity())return;if(importLoading)throw Error('文件正在解析，请稍候');
    const unknown=f.elements.ownerUnknown.checked,customer=unknown?null:M.CLIENTS.find(c=>c.name===f.elements.customer.value);if(!unknown&&!customer)throw Error('请选择归属客户');
    const data=buildOrderDraft(importResult,{customer:customer?.name||'',customerCode:customer?.code||'',warehouse:f.elements.warehouse.value,source:f.elements.source.value,reason:f.elements.reason.value,request:f.elements.request.value,originalTracking:f.elements.originalTracking.value,ticket:f.elements.ticket.value,remark:f.elements.remark.value});
    const o=M.createOrder(data);o.importFile=$('#rtImportFileName').textContent;M.log(o,'模板导入下单',o.products.length+' 个产品，共 '+M.totals(o).forecast+' 个');orders.unshift(o);save();tab='待受理';page=1;filters={};$('#rtFilter').reset();closeDrawer();render();toast('模板导入下单成功，等待受理');
  }catch(error){$('#rtImportError').textContent=error.message;}
}

const newProduct=()=>({id:M.id('P'),name:'',sku:'',image:'',quantity:1,weight:0,dimensions:[0,0,0],packing:0,returnedAt:'',tracking:'',requirement:'',location:'',reportedReceivedAt:'',reportedReceived:null,reportedBoxes:null});
const newPackage=()=>({id:M.id('PK'),tracking:'',carrier:'UPS',items:[],forecast:1,returnedAt:'',shipped:'',eta:'',logistics:'运输中',note:'',received:false});
function productCard(p,index){return `<article class="rt-form-row rt-form-product" data-rt-product="${esc(p.id)}"><header><strong>产品 ${index+1}</strong>${btn('删除产品','remove-product',false,`data-rt-product-id="${esc(p.id)}" ${draft.products.length===1?'disabled':''}`)}</header><div class="rt-product-grid">${field('产品名称',input('name','text',p.name,'required'),true)}${field('SKU',input('sku','text',p.sku,'required'),true)}${field('预报产品数量(个)',input('quantity','number',p.quantity,'min="1" step="1" required'),true)}${field('预报产品图片',`<div class="rt-image-control"><div data-rt-product-preview class="cl-product">${image(p)}</div>${input('image','text',p.image,'placeholder="图片链接，或上传图片"')}<label class="cl-btn rt-file-label">上传图片<input type="file" data-rt-upload-product="${esc(p.id)}" accept="image/*" hidden></label></div>`)}${field('预报产品重量(单个产品KG)',input('weight','number',p.weight,'min="0" step="any"'))}${field('外箱尺寸(cm)',`<div class="cl-range">${['length','width','height'].map((key,i)=>input(key,'number',p.dimensions?.[i]??0,`min="0" step="any" aria-label="外箱${['长','宽','高'][i]}" placeholder="${['长','宽','高'][i]}"`)).join('')}</div>`)}${field('操作要求',`<textarea name="requirement" placeholder="填写该产品的操作要求">${esc(p.requirement||'')}</textarea>`)}${field('货物目前所在地',input('location','text',p.location||'','placeholder="如客户所在地、运输途中、仓库退件区"'))}${field('装箱数量',input('packing','number',p.packing,'min="0" step="1"'))}${field('退仓时间',input('returnedAt','datetime-local',dateInput(p.returnedAt),'step="1"'))}${field('追踪单号','<div class="rt-note-muted">在下方“退回包裹”中登记并关联产品</div>')}${field('入库时间',`<div class="rt-note-muted">${p.reportedReceivedAt?'模板填写：'+esc(p.reportedReceivedAt)+'<br>':''}仓库收货后回填实际时间</div>`)}${field('入库个数(个)',`<div class="rt-note-muted">${p.reportedReceived!==null&&p.reportedReceived!==undefined?'模板填写：'+p.reportedReceived+' 个<br>':''}仓库收货后回填实收个数</div>`)}${field('入库件数(箱)',`<div class="rt-note-muted">${p.reportedBoxes!==null&&p.reportedBoxes!==undefined?'模板填写：'+p.reportedBoxes+' 箱<br>':''}仓库收货后回填实收箱数</div>`)}</div></article>`;}
function packageCard(p,index){return `<article class="rt-form-row" data-rt-package-card="${esc(p.id)}"><header><strong>包裹 ${index+1}</strong>${btn('删除包裹','remove-package',false,`data-rt-package-id="${esc(p.id)}"`)}</header><div class="rt-package-grid">${field('追踪单号',input('tracking','text',p.tracking,'required'),true)}${field('物流商',`<select name="carrier">${['UPS','FedEx','USPS','AMZL','其他'].map(v=>option(v,v,p.carrier)).join('')}</select>`,true)}${field('该包裹预报产品个数',input('forecast','number',p.forecast,'min="1" step="1" required'))}${field('退仓时间',input('returnedAt','datetime-local',dateInput(p.returnedAt),'step="1"'))}${field('发运时间',input('shipped','datetime-local',dateInput(p.shipped),'step="1"'))}${field('预计送达时间',input('eta','datetime-local',dateInput(p.eta),'step="1"'))}${field('备注',input('note','text',p.note))}</div><div class="rt-product-mapping"><strong>关联产品及包裹内预报个数（SKU 未核实时可留空）</strong>${draft.products.map(product=>{const mapped=p.items.find(i=>i.productId===product.id);return `<label><input type="checkbox" data-rt-map-product="${esc(product.id)}" ${mapped?'checked':''}><span>${esc(product.name||'未命名产品')} · ${esc(product.sku||'待填写 SKU')}</span><input type="number" min="1" step="1" value="${mapped?.quantity??1}" data-rt-map-quantity="${esc(product.id)}" aria-label="${esc(product.name||'产品')}在本包裹内的预报个数"></label>`;}).join('')}</div></article>`;}
function form(o=null){$('#rtDrawer').classList.remove('cl-import-overlay');importSequence++;current=o;drawerMode='form';draft=o?structuredClone(o):{customer:'',customerCode:'',warehouse:'',source:M.SOURCES[0],reason:'客户退货',request:'暂时未确定',originalTracking:'',ticket:'',remark:'',products:[newProduct()],packages:[]};renderForm();}
function renderForm(){const d=draft;$('#rtDrawer').innerHTML=`<section class="cl-drawer rt-drawer" role="dialog" aria-modal="true" aria-label="${current?'编辑退换货预报':'新增退换货'}"><header class="cl-drawer-header"><div><h2>${current?'编辑退换货预报':'新增退换货'}</h2><p class="cl-muted">产品与包裹分别登记，可在受理后补充全部追踪单号</p></div><button class="cl-close" data-rt-action="drawer-close" aria-label="关闭">×</button></header><div class="cl-drawer-body"><form id="rtOrderForm"><section class="cl-section"><h3>基础信息</h3><div class="rt-product-grid">${field('客户名称',input('customer','search',d.customer,'required list="rtCustomers" placeholder="搜索或选择客户"'),true)}${field('客户编码',input('customerCode','text',d.customerCode,'readonly'))}${field('退回仓库',`<select name="warehouse" required>${options(M.WAREHOUSES,d.warehouse,'请选择仓库')}</select>`,true)}${field('退件来源',`<select name="source">${M.SOURCES.map(v=>option(v,v,d.source)).join('')}</select>`)}${field('退件原因',`<select name="reason">${['客户退货','拒收','错投','地址问题','其他','待核实'].map(v=>option(v,v,d.reason)).join('')}</select>`)}${field('业务处理诉求',`<select name="request">${['换标重新派送','清点','暂时未确定','自提','销毁','其他'].map(v=>option(v,v,d.request)).join('')}</select>`)}${field('原运单号',input('originalTracking','text',d.originalTracking))}${field('退件核实工单号',input('ticket','text',d.ticket))}${field('申请备注',`<textarea name="remark" maxlength="1000">${esc(d.remark||'')}</textarea>`,false,true)}</div><label class="cl-consent"><input name="ownerUnknown" type="checkbox" ${!d.customer&&d.source!=='客户预报'?'checked':''}>客户归属待核实（代理反馈或其他退件）</label><p class="cl-muted">处理诉求仅记录预期需求，实际操作需另下正式指令。</p></section><section class="cl-section"><div class="cl-heading"><h3 style="margin:0">预报货物信息</h3>${btn('＋ 添加产品','add-product')}</div>${d.products.map(productCard).join('')}<p class="cl-muted">装箱数量保留原模板名称，口径待业务确认；入库字段由仓库登记。</p></section><section class="cl-section"><div class="cl-heading"><h3 style="margin:0">退回包裹</h3>${btn('＋ 添加包裹','add-package')}</div>${d.packages.map(packageCard).join('')||'<div class="rt-note-muted">可在受理后补充追踪号。同一个包裹支持多个 SKU，同一产品可分配到多个包裹。</div>'}</section><div class="cl-notice">退件是否入仓以海外仓实际收到为准，物流官网签收仅作参考。请及时提供全部追踪单号；带电、危险品需单独确认服务与报价。</div><p id="rtFormError" class="cl-error" role="alert"></p></form></div><footer class="cl-drawer-footer">${btn('取消','cancel-form')}<button class="cl-btn primary" type="submit" form="rtOrderForm">${current?'保存预报':'提交申请'}</button></footer></section>`;$('#rtDrawer').hidden=false;syncCustomer();}
function syncCustomer(){const f=$('#rtOrderForm');if(!f)return;const unknown=f.elements.ownerUnknown.checked;f.elements.customer.disabled=unknown;f.elements.customer.required=!unknown;f.elements.customerCode.value=unknown?'':M.CLIENTS.find(c=>c.name===f.elements.customer.value)?.code||'';}
function readPackage(card){const val=name=>card.querySelector(`[name="${name}"]`).value;const items=[...card.querySelectorAll('[data-rt-map-product]')].filter(c=>c.checked).map(c=>({productId:c.dataset.rtMapProduct,quantity:Number(card.querySelector(`[data-rt-map-quantity="${c.dataset.rtMapProduct}"]`).value)}));return {id:card.dataset.rtPackageCard,tracking:val('tracking').trim(),carrier:val('carrier'),forecast:Number(val('forecast')),items,returnedAt:val('returnedAt'),shipped:val('shipped'),eta:val('eta'),note:val('note'),logistics:draft.packages.find(p=>p.id===card.dataset.rtPackageCard)?.logistics||(val('shipped')?'运输中':'未发运'),received:false};}
function captureDraft(){const f=$('#rtOrderForm');if(!f)return;for(const key of['customer','customerCode','warehouse','source','reason','request','originalTracking','ticket','remark'])draft[key]=f.elements[key].value;if(f.elements.ownerUnknown.checked){draft.customer='';draft.customerCode='';}draft.products=[...f.querySelectorAll('[data-rt-product]')].map(card=>{const val=key=>card.querySelector(`[name="${key}"]`).value;return {id:card.dataset.rtProduct,name:val('name').trim(),sku:val('sku').trim(),image:val('image'),quantity:Number(val('quantity')),weight:Number(val('weight')),dimensions:['length','width','height'].map(key=>Number(val(key))),packing:Number(val('packing')),returnedAt:val('returnedAt'),requirement:val('requirement'),location:val('location'),tracking:draft.products.find(p=>p.id===card.dataset.rtProduct)?.tracking||'',reportedReceivedAt:draft.products.find(p=>p.id===card.dataset.rtProduct)?.reportedReceivedAt||'',reportedReceived:draft.products.find(p=>p.id===card.dataset.rtProduct)?.reportedReceived??null,reportedBoxes:draft.products.find(p=>p.id===card.dataset.rtProduct)?.reportedBoxes??null};});draft.packages=[...f.querySelectorAll('[data-rt-package-card]')].map(readPackage);}
function submitOrder(e){e.preventDefault();try{captureDraft();if(draft.source==='客户预报'&&!draft.customer)throw Error('客户预报需选择客户');if(draft.customer&&!draft.customerCode)throw Error('请从客户列表选择客户');const previous=current;if(previous)M.editOrder(previous,draft);else orders.unshift(M.createOrder(draft));save();tab=previous?previous.status:'待受理';page=1;filters={};$('#rtFilter').reset();render();draft=null;if(previous)detail(previous);else{$('#rtDrawer').hidden=true;drawerMode='';current=null;}toast(previous?'预报已更新':'退换货申请已提交，等待受理');}catch(error){$('#rtFormError').textContent=error.message;}}

function modal(title,body,commit,label='确认'){modalCommit=commit;$('#rtModal').innerHTML=`<section class="cl-modal rt-modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><header><h3>${title}</h3><button class="cl-close" data-rt-action="modal-close" aria-label="关闭弹窗">×</button></header><form id="rtModalForm"><div class="cl-modal-body">${body}<p id="rtModalError" class="cl-error" role="alert"></p></div><footer>${btn('取消','modal-close')}<button class="cl-btn primary" type="submit">${label}</button></footer></form></section>`;$('#rtModal').hidden=false;$('#rtModal').querySelector('input,select,textarea')?.focus();}
function selectedBoxes(f){return [...f.querySelectorAll('input[name="boxId"]:checked')].map(c=>c.value);}
function boxesControl(o,kind){return `<div class="cl-heading"><span class="cl-muted">按具体箱号选择</span>${btn('全选可选箱','select-boxes')}</div><div class="rt-box-grid">${o.boxes.filter(b=>!b.outbound).map(b=>{const reason=kind==='instruct'?(!b.claimed?'未认领':b.customerCode!==o.customerCode?'归属不匹配':b.reservedBy?'已被指令占用':''):b.claimed?'已认领':'';return `<label class="rt-box-option ${reason?'is-disabled':''}"><input name="boxId" type="checkbox" value="${esc(b.id)}" ${reason?'disabled':''}><span><strong>${esc(b.id)}</strong><small>${esc(packageName(o.packages.find(p=>p.id===b.packageId)||{}))}</small><small>${reason||'可选'} · ${b.counted?'已清点':'未清点内件'}</small></span></label>`;}).join('')||'<div class="rt-note-muted">暂无实际在库箱</div>'}</div>`;}
function trackForm(o){if(!M.can(o,'track'))throw Error('当前状态不可登记追踪号');const p=newPackage();modal('登记退回包裹',`<div class="rt-package-grid">${field('追踪单号',input('tracking','text','','required'),true)}${field('物流商',`<select name="carrier">${['UPS','FedEx','USPS','AMZL','其他'].map(v=>option(v)).join('')}</select>`,true)}${field('该包裹预报产品个数',input('forecast','number',1,'min="1" step="1" required'),true)}${field('退仓时间',input('returnedAt','datetime-local','','step="1"'))}${field('发运时间',input('shipped','datetime-local',dateInput(M.now()),'step="1"'))}${field('预计送达时间',input('eta','datetime-local','','step="1"'))}${field('备注',input('note'))}</div><div class="rt-product-mapping"><strong>关联 SKU 及包裹产品个数（SKU 未核实时可留空）</strong>${o.products.map(p=>`<label><input type="checkbox" data-rt-map-product="${p.id}"><span>${esc(p.name)} · ${esc(p.sku)}</span><input type="number" min="1" step="1" value="1" data-rt-map-quantity="${p.id}" aria-label="${esc(p.name)}在本包裹内的个数"></label>`).join('')}</div>`,f=>{const items=[...f.querySelectorAll('[data-rt-map-product]')].filter(c=>c.checked).map(c=>({productId:c.dataset.rtMapProduct,quantity:Number(f.querySelector(`[data-rt-map-quantity="${c.dataset.rtMapProduct}"]`).value)}));M.addPackage(o,{...p,tracking:f.elements.tracking.value,carrier:f.elements.carrier.value,items,forecast:Number(f.elements.forecast.value),returnedAt:f.elements.returnedAt.value,shipped:f.elements.shipped.value,eta:f.elements.eta.value,note:f.elements.note.value});},'保存追踪信息');}
function receiveForm(o,packageId=''){if(!M.can(o,'receive'))throw Error('当前状态不可登记收货');const packages=o.packages.filter(p=>!p.received);modal('仓库实际收货登记',`${field('追踪包裹',`<select name="packageId" required>${packages.map(p=>option(p.id,packageName(p),packageId)).join('')}</select>`,true)}${field('仓库',input('warehouse','text',o.warehouse,'readonly'))}${field('实际入库时间',input('time','datetime-local',dateInput(M.now()),'step="1" required'),true)}${field('本批入库件数(箱)',input('boxes','number',1,'min="1" step="1" required'),true)}${field('内件清点',`<select name="counted"><option value="0">仅收包裹，未开箱清点</option><option value="1">已清点，登记各 SKU 实收个数</option></select>`)}<div id="rtReceiptItems">${o.products.map(p=>field(esc(p.name)+' · '+esc(p.sku),input('received-'+p.id,'number',0,'min="0" step="1" disabled'))).join('')}</div><p class="rt-batch-summary" id="rtReceiptCount">本批入库个数：未清点</p>${field('差异原因',input('difference','text','','placeholder="短少、超收、错件等；有差异请说明"'))}${field('收货备注','<textarea name="note"></textarea>')}${field('收货图片',input('image','text','','placeholder="图片链接或上传图片"')+'<label class="cl-btn rt-file-label">上传图片<input type="file" data-rt-upload-receipt accept="image/*" hidden></label><div class="cl-product" id="rtReceiptPreview"></div>')}<label class="cl-consent"><input type="checkbox" name="complete" checked>本包裹已核实收齐（后续还有批次时取消勾选）</label><div class="cl-notice" style="margin-top:14px">仅收到包裹时可登记箱数，内件个数保持未清点，不按预报推定。</div>`,f=>M.receive(o,{packageId:f.elements.packageId.value,time:f.elements.time.value,boxes:Number(f.elements.boxes.value),counted:f.elements.counted.value==='1',items:f.elements.counted.value==='1'?o.products.map(p=>({productId:p.id,quantity:Number(f.elements['received-'+p.id].value)})).filter(i=>i.quantity>0):[],note:f.elements.note.value,difference:f.elements.difference.value,image:f.elements.image.value,complete:f.elements.complete.checked}),'确认实际收货');}
function syncReceipt(){const f=$('#rtModalForm');if(!f?.elements.counted)return;const counted=f.elements.counted.value==='1';for(const control of f.querySelectorAll('[name^="received-"]'))control.disabled=!counted;$('#rtReceiptCount').textContent='本批入库个数：'+(counted?[...f.querySelectorAll('[name^="received-"]')].reduce((n,c)=>n+Number(c.value||0),0)+' 个':'未清点');}
function claimForm(o){if(!M.can(o,'claim'))throw Error('暂无可确认认领的箱');modal('确认客户认领',`${field('归属客户',`<select name="customer" required>${option('','请选择确认的客户')}${M.CLIENTS.map(c=>option(c.name,c.name+' · '+c.code,o.customer)).join('')}</select>`,true)}${boxesControl(o,'claim')}${field('认领备注','<textarea name="note"></textarea>')}<div class="cl-notice">确认所选箱的实际客户归属，未认领箱不可提交正式处理指令。</div>`,f=>{const c=M.CLIENTS.find(c=>c.name===f.elements.customer.value);if(!c)throw Error('请选择客户');M.claim(o,{boxIds:selectedBoxes(f),customer:c.name,customerCode:c.code,note:f.elements.note.value});},'确认认领');}
function instructionForm(o){if(!M.can(o,'instruct'))throw Error('暂无已收、已认领且未占用的可用箱');modal('下指令',`<div class="cl-notice" style="margin-bottom:16px">${esc(o.id)} · ${esc(o.customer)} · ${esc(o.warehouse)}</div>${field('指令类型',`<select name="type">${['库内增值服务','发货计划','自提','销毁'].map(v=>option(v)).join('')}</select>`,true)}${boxesControl(o,'instruct')}${field('操作要求','<textarea name="note" required placeholder="请输入具体操作内容"></textarea>',true)}<div class="cl-notice">提交后预留所选箱，审批和仓库操作由统一指令管理执行。</div>`,f=>{const before=structuredClone(o),i=M.instruct(o,{type:f.elements.type.value,boxIds:selectedBoxes(f),note:f.elements.note.value});try{window.ReturnsBridge?.publish(o,i);}catch(error){Object.assign(o,before);throw error;}},'提交至指令管理');}
function exportCSV(){const data=exportProductGrid(filtered()),safe=value=>/^[=+@\-\t\r]/.test(String(value??''))?"'"+value:String(value??'');const csv='\uFEFF'+data.map(row=>row.map(value=>'"'+safe(value).replaceAll('"','""')+'"').join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='退换货产品明细_'+M.now().slice(0,10)+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('已导出筛选申请的全部模板字段，每个产品一行');}
function listLogs(){
  $('#rtDrawer').classList.remove('cl-import-overlay');importSequence++;
  current=null;draft=null;drawerMode='logs';
  const rows=filtered().flatMap(o=>o.logs.map(log=>({o,log}))).sort((a,b)=>b.log.time.localeCompare(a.log.time));
  $('#rtDrawer').innerHTML=`<section class="cl-drawer rt-drawer" role="dialog" aria-modal="true" aria-label="退换货操作日志"><header class="cl-drawer-header"><div><h2>退换货操作日志</h2><p class="cl-muted">${esc(tab)} · 当前筛选范围 · 共 ${rows.length} 条记录</p></div><button class="cl-close" data-rt-action="drawer-close" aria-label="关闭日志">×</button></header><div class="cl-drawer-body"><section class="cl-section">${table(['操作时间','退换货单号','客户名称','操作人','操作类型','变更内容'],rows.map(({o,log})=>`<tr data-rt-order="${esc(o.id)}"><td>${dt(log.time)}</td><td><button class="cl-link cl-mono" data-rt-action="detail">${esc(o.id)}</button></td><td>${esc(o.customer||'待识别货主')}</td><td>${esc(log.operator)}</td><td>${esc(log.action)}</td><td class="rt-log-note">${esc(log.note)}</td></tr>`).join(''))}</section></div><footer class="cl-drawer-footer">${btn('关闭','drawer-close')}</footer></section>`;$('#rtDrawer').hidden=false;
}
function closeDrawer(){$('#rtDrawer').hidden=true;$('#rtDrawer').classList.remove('cl-import-overlay');importSequence++;importLoading=false;current=null;draft=null;drawerMode='';}
function action(name,target){
  const row=target.closest('[data-rt-order]'),o=row?orders.find(o=>o.id===row.dataset.rtOrder):current;
  if(name==='drawer-close'){closeDrawer();return;}if(name==='modal-close'){$('#rtModal').hidden=true;modalCommit=null;return;}
  if(name==='create'){createImport();return;}if(name==='reset'){$('#rtFilter').reset();filters={};tab='全部';page=1;render();return;}
  if(name==='expand'){const e=$('#rtAdvanced');e.hidden=!e.hidden;target.textContent=e.hidden?'展开 ⌄':'收起 ⌃';return;}
  if(name==='list-logs'){listLogs();return;}
  if(name==='columns'){$('#rtColumns').hidden=!$('#rtColumns').hidden;return;}if(name==='export'){exportCSV();return;}if(name==='prev'||name==='next'){page+=name==='prev'?-1:1;render();return;}
  if(name==='cancel-form'){const previous=current;draft=null;if(previous)detail(previous);else closeDrawer();return;}
  if(name==='add-product'||name==='remove-product'||name==='add-package'||name==='remove-package'){
    captureDraft();if(name==='add-product')draft.products.push(newProduct());if(name==='add-package')draft.packages.push(newPackage());
    if(name==='remove-product'){const id=target.dataset.rtProductId;draft.products=draft.products.filter(p=>p.id!==id);for(const p of draft.packages){p.items=p.items.filter(i=>i.productId!==id);}}
    if(name==='remove-package')draft.packages=draft.packages.filter(p=>p.id!==target.dataset.rtPackageId);renderForm();return;
  }
  if(name==='select-boxes'){for(const c of $('#rtModalForm').querySelectorAll('input[name="boxId"]:not(:disabled)'))c.checked=true;return;}
  if(!o)return;current=o;
  if(name==='detail'){detail(o);return;}if(name==='packages'){detail(o,2);return;}if(name==='logs'){detail(o,6);return;}
  if(name==='edit'){if(!M.can(o,'edit'))throw Error('当前状态不可编辑预报');form(o);return;}
  if(name==='track'){trackForm(o);return;}if(name==='receive'){receiveForm(o,target.dataset.rtPackage||'');return;}if(name==='claim'){claimForm(o);return;}if(name==='instruct'){instructionForm(o);return;}
  if(name==='open-instruction'){const id=target.dataset.rtInstruction;if(!window.ReturnsBridge)throw Error('指令管理暂未加载，请刷新页面');if(window.ReturnsBridge.openInstruction(id)!==false)closeDrawer();return;}
  if(name==='confirm-outbound'){const i=o.instructions.find(i=>i.id===target.dataset.rtInstruction);if(!i||i.status!=='指令处理完成、待出库'||i.type==='库内增值服务')throw Error('当前指令不可确认实际出库');if(!window.ReturnsBridge?.confirmOutbound)throw Error('指令管理暂未加载，请刷新页面');if(window.ReturnsBridge.confirmOutbound(i.id)){reconcile();render();detail(o,5);toast(i.type==='销毁'?'已确认实际销毁':i.type==='自提'?'已确认实际提货':'已确认实际出库');}return;}
  if(name==='accept'){if(!M.can(o,'accept'))throw Error('当前状态不可受理');modal('受理退换货申请',`<div class="cl-notice" style="margin-bottom:16px">${esc(o.id)} · ${esc(o.warehouse)}<br>请确认仓库可接收退件，特殊货物需单独确认。</div>${field('确认退回仓地址',input('address','text',o.returnAddress||o.warehouse+' · 退件接收区（模拟地址）','required'),true)}${field('接收联系人',input('contact','text',o.returnContact||'Returns Desk（模拟）','required'),true)}`,f=>{M.accept(o);o.returnAddress=f.elements.address.value;o.returnContact=f.elements.contact.value;M.log(o,'确认退回信息',o.returnAddress+'；'+o.returnContact);},'确认受理');return;}
  if(name==='reject'||name==='close'){if(!M.can(o,name))throw Error('已有收货或有效指令，不能直接关闭，请核实处理');modal(name==='reject'?'拒绝受理':'取消退换货申请',`${field(name==='reject'?'拒绝原因':'关闭原因','<textarea name="reason" required></textarea>',true)}<div class="cl-notice">关闭结果保留在详情；已实际收货或存在有效指令时不允许简单取消。</div>`,f=>M.close(o,f.elements.reason.value,name==='reject'),name==='reject'?'确认拒绝':'确认取消');return;}
  if(name==='notify'){if(!M.can(o,'notify'))throw Error('暂无待通知认领的箱');modal('通知客户认领',`${boxesControl(o,'claim')}<div class="cl-notice">记录客服通知时间，等待客户确认所属包裹。本原型模拟通知，不发送消息。</div>`,f=>M.notify(o,selectedBoxes(f)),'记录通知');return;}
  if(name==='logistics'){if(!active(o))throw Error('已结束申请仅支持查看');const selected=target.dataset.rtPackage;modal('物流反馈',`${field('追踪包裹',`<select name="packageId">${o.packages.map(p=>option(p.id,packageName(p),selected)).join('')}</select>`)}${field('物流状态',`<select name="logistics">${['运输中','物流已妥投','待核实','退回异常'].map(v=>option(v)).join('')}</select>`)}<div class="cl-notice">物流妥投只进入待仓库确认，不写入实际收货或库存。</div>`,f=>M.updateLogistics(o,f.elements.packageId.value,f.elements.logistics.value),'保存反馈');return;}
  if(name==='ticket'){if(!active(o))throw Error('已结束申请仅支持查看');modal('关联退件核实工单',`${field('工单号',input('ticket','text',o.ticket,'required'),true)}${field('工单进度',`<select name="ticketStatus">${['待核实','核实中','已收到','已关闭（未收到）'].map(v=>option(v,v,o.ticketStatus)).join('')}</select>`)}<div class="cl-notice">关闭核实工单不会自动确认收货、关闭退换货申请或扣减库存。</div>`,f=>{o.ticket=f.elements.ticket.value;o.ticketStatus=f.elements.ticketStatus.value;M.log(o,'更新核实工单',o.ticket+' · '+o.ticketStatus);});return;}
  if(name==='fee'){if(!M.can(o,'fee'))throw Error('当前状态不可登记费用');modal('登记报价 / 费用',`${field('费用项目',input('name','text','','required list="rtFeeNames"')+'<datalist id="rtFeeNames">'+['入仓','开箱','清点','换标','SKU 分拣','重打板','快递出库','卡派出库','自提','销毁','仓储'].map(v=>option(v)).join('')+'</datalist>',true)}${field('金额',input('amount','number','','min="0" step="0.01" required'),true)}${field('币种',`<select name="currency"><option>USD</option><option>CAD</option><option>CNY</option></select>`)}${field('报价备注','<textarea name="note"></textarea>')}`,f=>M.addFee(o,{name:f.elements.name.value,amount:Number(f.elements.amount.value),currency:f.elements.currency.value,note:f.elements.note.value}),'保存记录');}
}
document.addEventListener('click',e=>{
  const img=e.target.closest('[data-rt-image]');if(img){$('#rtModal').innerHTML=`<section class="cl-modal" role="dialog" aria-modal="true" aria-label="图片预览"><header><h3>图片预览</h3><button class="cl-close" data-rt-action="modal-close" aria-label="关闭">×</button></header><div class="cl-modal-body"><img class="cl-image-preview" src="${esc(img.dataset.rtImage)}" alt="产品 / 收货图片"></div></section>`;modalCommit=null;$('#rtModal').hidden=false;return;}
  const t=e.target.closest('[data-rt-tab]');if(t){tab=t.dataset.rtTab;page=1;render();return;}const d=e.target.closest('[data-rt-detail-tab]');if(d){detail(current,Number(d.dataset.rtDetailTab));return;}const p=e.target.closest('[data-rt-page]');if(p){page=Number(p.dataset.rtPage);render();return;}
  const a=e.target.closest('[data-rt-action]');if(a&&!a.disabled){try{action(a.dataset.rtAction,a);}catch(error){toast(error.message);}return;}if(e.target===$('#rtModal')){$('#rtModal').hidden=true;modalCommit=null;}
});
document.addEventListener('change',e=>{
  const t=e.target;if(t.id==='rtImportFile'&&t.files?.[0])loadImport(t.files[0]);if(t.matches('#rtImportForm [name="customer"],#rtImportForm [name="source"],#rtImportForm [name="ownerUnknown"]'))syncImportCustomer();if(t.matches('[data-rt-column]')){if(t.checked)hiddenCols.delete(t.dataset.rtColumn);else hiddenCols.add(t.dataset.rtColumn);render();}if(t.id==='rtPageSize'){size=Number(t.value);page=1;render();}if(t.id==='rtSort'){sort=t.value;render();}
  if(t.matches('#rtOrderForm [name="customer"],#rtOrderForm [name="ownerUnknown"]'))syncCustomer();
  if(t.matches('[data-rt-map-product],[data-rt-map-quantity]')){const card=t.closest('[data-rt-package-card]');if(card)card.querySelector('[name="forecast"]').value=readPackage(card).forecast;}
  if(t.matches('#rtModalForm [name="counted"],#rtModalForm [name^="received-"]'))syncReceipt();
  if(t.matches('[data-rt-upload-product],[data-rt-upload-receipt]')&&t.files?.[0]){const file=t.files[0];if(!file.type.startsWith('image/')){toast('请选择图片文件');return;}if(file.size>2*1024*1024){toast('图片请控制在 2MB 以内');return;}const reader=new FileReader(),pid=t.dataset.rtUploadProduct;reader.onload=()=>{if(pid){const card=$('#rtOrderForm')?.querySelector(`[data-rt-product="${pid}"]`);if(!card)return;card.querySelector('[name="image"]').value=reader.result;card.querySelector('[data-rt-product-preview]').innerHTML=image({name:'产品图片',image:reader.result});}else{const f=$('#rtModalForm');if(!f?.elements.image)return;f.elements.image.value=reader.result;$('#rtReceiptPreview').innerHTML=image({name:'收货附件',image:reader.result});}};reader.readAsDataURL(file);}
});
document.addEventListener('submit',e=>{if(e.target.id==='rtImportForm')submitImport(e);if(e.target.id==='rtOrderForm')submitOrder(e);if(e.target.id==='rtModalForm'){e.preventDefault();try{if(!modalCommit)return;modalCommit(e.target);save();$('#rtModal').hidden=true;modalCommit=null;render();if(current&&drawerMode==='detail')detail(current,detailTab);toast('操作已保存');}catch(error){$('#rtModalError').textContent=error.message;}}});
$('#rtFilter').onsubmit=e=>{e.preventDefault();const next=Object.fromEntries(new FormData(e.target));for(const [a,b] of[['from','to'],['receivedFrom','receivedTo'],['returnedFrom','returnedTo']])if(next[a]&&next[b]&&next[a]>next[b]){toast('开始日期须早于或等于结束日期');return;}for(const key of ['quantity','weight','packing'])if(next[key+'Min']!==''&&next[key+'Max']!==''&&Number(next[key+'Min'])>Number(next[key+'Max'])){toast('最小值须小于或等于最大值');return;}filters=next;page=1;render();};
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(!$('#rtModal').hidden){$('#rtModal').hidden=true;modalCommit=null;}else closeDrawer();}});
document.addEventListener('warehouse-page-change',()=>{importSequence++;importLoading=false;$('#rtDrawer').classList.remove('cl-import-overlay');pageEl.hidden=true;$('#rtDrawer').hidden=true;$('#rtModal').hidden=true;current=null;draft=null;drawerMode='';modalCommit=null;});
window.ReturnsUI={open};reconcile();render();if(new URLSearchParams(location.search).get('page')==='returns')open();
